CREATE TABLE IF NOT EXISTS public.diabetes_patients (
    patient_id          VARCHAR(50) PRIMARY KEY,
    name                VARCHAR(150) NOT NULL,
    age                 INT CHECK (age >= 0 AND age <= 120),
    gender              VARCHAR(10),
    diagnosis_date      DATE,
    
    blood_sugar         NUMERIC(6,2),         -- mg/dL
    hba1c               NUMERIC(4,2),         -- % (like 6.5)
    
    height_cm           NUMERIC(5,2),
    weight_kg           NUMERIC(5,2),

    systolic_bp         INT,
    diastolic_bp        INT,

    smoking_status      VARCHAR(30),          -- "current", "former", "never"
    medications         TEXT,                 -- comma-separated or JSON
    
    last_visit          TIMESTAMP,
    created_at          TIMESTAMP DEFAULT NOW()
);

